"""Transparent, deterministic demo assistant. Does not pretend to be an LLM."""
import re

SOURCE = '«Инструкции для кейса-1», предоставлены организатором'
KNOWLEDGE = [
 dict(id='projector', title='Как подключить ноутбук к проектору', category='equipment', source=SOURCE + ', раздел 1', summary='Подключение, выбор источника и режим отображения.',
 steps=['Осмотрите оборудование и кабели. При видимых повреждениях не подключайте устройство и сообщите сотруднику.', 'Подключите предусмотренный кабель HDMI или VGA к компьютеру и проектору. Не прикладывайте силу к разъёмам.', 'Включите проектор штатной кнопкой, дождитесь готовности, затем включите компьютер.', 'Выберите на проекторе соответствующий источник сигнала HDMI или VGA.', 'В Windows нажмите Win + P и выберите «Дублировать». Проверьте изображение.', 'Если изображения нет, проверьте источник, внешнее подключение неповреждённого кабеля и режим отображения. Если это не помогло, прекратите настройку и обратитесь к сотруднику.'], warning='Не разбирайте проектор, не ремонтируйте кабели и разъёмы, не перемещайте закреплённое оборудование.'),
 dict(id='printer', title='Что проверить, если принтер не печатает', category='equipment', source=SOURCE + ', раздел 2', summary='Безопасная первичная проверка перед обращением.',
 steps=['Проверьте, включён ли принтер и есть ли сообщение об ошибке на дисплее.', 'Убедитесь, что бумага в лотке лежит ровно, а в окне печати выбран нужный принтер.', 'Проверьте подключение компьютера к сети или принтеру способом, принятым в кабинете.', 'Проверьте, не приостановлена ли очередь. Не удаляйте чужие задания и не меняйте системные настройки без разрешения.', 'Следуйте только понятным штатным подсказкам дисплея. Если проблема осталась, запишите ошибку, кабинет и название принтера, затем создайте заявку.'], warning='Не вскрывайте корпус и картридж, не извлекайте внутренние детали, не касайтесь нагретых или движущихся частей.'),
 dict(id='computer', title='Правила работы за компьютером колледжа', category='equipment', source=SOURCE + ', раздел 3', summary='Учётные записи, файлы и бережное использование техники.',
 steps=['Используйте компьютер по учебному заданию и указаниям преподавателя. Осмотрите технику на видимые повреждения.', 'Без разрешения не устанавливайте программы и не меняйте системные, сетевые настройки и параметры безопасности.', 'Не сообщайте пароли, не используйте чужие аккаунты и не подключайте неизвестные USB-накопители.', 'Держите напитки и еду вдали от техники. Сохраняйте файлы в разрешённое место.', 'После работы сохраните файлы, выйдите из личных аккаунтов и завершите работу согласно указаниям сотрудника.'], warning='При зависании, перегреве, необычных звуках или ошибке сообщите сотруднику. Не разбирайте устройство. Локальные правила входа и хранения файлов уточняйте у колледжа.'),
 dict(id='fault', title='Как сообщить о неисправности', category='other', source=SOURCE + ', раздел 4', summary='Место, описание и безопасное фото проблемы.',
 steps=['Прекратите использование неисправного или повреждённого устройства.', 'Не ремонтируйте оборудование, не вскрывайте корпус и не вмешивайтесь в электропроводку.', 'Укажите корпус, этаж и кабинет. Опишите, какое оборудование не работает, что произошло и когда.', 'Если безопасно, приложите фото устройства или ошибки. Не трогайте повреждённые части ради фотографии.', 'Откройте форму или QR помещения, выберите категорию, подтвердите отправку и сохраните секретную ссылку отслеживания.'], warning='При дыме, запахе гари или искрении отойдите, не трогайте оборудование и немедленно сообщите ответственному сотруднику. При непосредственной угрозе обратитесь в экстренную службу.'),
 dict(id='tracking', title='Где посмотреть статус заявки', category='other', source='Руководство приложения УПК: отслеживание', summary='Безопасная ссылка, история и ответы сотрудника.',
 steps=['После отправки сохраните ссылку или код доступа. Один номер заявки не предоставляет доступа.', 'Откройте сохранённую ссылку либо раздел «Мои обращения» и введите код доступа.', 'Страница показывает актуальный статус, публичные комментарии и историю. Нажмите «Обновить» для проверки.', 'Если сотрудник запросил уточнение, ответьте в карточке. После решения можно оценить результат.'], warning='Не публикуйте секретную ссылку: она открывает доступ к вашей заявке.'),
 dict(id='category', title='Как выбрать категорию', category='other', source='Руководство приложения УПК: справочник категорий', summary='Оборудование, интернет, электрика, имущество и уборка.',
 steps=['Проектор, компьютер и принтер — «Оборудование». Сеть и Wi-Fi — «Интернет и связь».', 'Розетки и освещение — «Электрика». Мебель, окна и двери — «Имущество».', 'Загрязнения — «Уборка». Протечки — «Сантехника». Если сомневаетесь, выберите «Другое».'], warning='Категория не заменяет описание проблемы и место.'),
 dict(id='property', title='Повреждено имущество: что указать', category='property', source=SOURCE + ', раздел 4; подсказка формы', summary='Как описать сломанную мебель, дверь или окно.',
 steps=['Не используйте повреждённый предмет, если это небезопасно.', 'Укажите помещение и предмет: стол, стул, ручка окна или дверь.', 'Опишите повреждение, при возможности безопасно приложите фото и создайте заявку.'], warning='Не пытайтесь ремонтировать повреждение самостоятельно.'),
]

def classify(text):
 t = text.lower().replace('ё', 'е').strip()
 r = dict(mode='demo', kind='unknown', confidence='low', category='other', priority='normal', title=text.strip()[:100], message='В проверенной базе недостаточно информации. Уточните вопрос или передайте его сотруднику УПК.', should_create=True, knowledge_id=None, source=None)
 if re.search(r'искр|дым|горит|гари|пожар|оголен|током|замкнул|затоп|прорвало|(?:ремонт|замен|помен|чин|разобра|вскры|обойти|отключить защит).{0,35}(?:проводк|розет|электр|блок питан|защит)', t):
  r.update(kind='danger', confidence='high', category='plumbing' if re.search('затоп|прорвало', t) else 'electric', priority='urgent', message='Отойдите от опасного места, не трогайте оборудование и не пытайтесь ремонтировать его. Немедленно сообщите ответственному сотруднику; при непосредственной угрозе обратитесь в экстренную службу. Заявка не заменяет срочное сообщение об опасности.')
  return r
 if re.search(r'парол|секрет|токен|ключ доступа', t):
  r.update(message='У меня нет доступа к паролям и секретам колледжа. Уточните официальный порядок получения доступа у ответственного сотрудника.')
  return r
 if re.search(r'когда|срок|сколько ждать', t) and not re.search(r'случилось|заметил', t):
  r.update(message='Срок ремонта мне неизвестен. Проверьте статус по секретной ссылке заявки или задайте вопрос сотруднику в комментариях.', knowledge_id='tracking')
  return r
 for cat, pattern in [('electric',r'розет|свет|ламп|освещ|электр|проводк'),('plumbing',r'вода|воды|кран|течет|протеч|труба|сануз'),('network',r'wi.?fi|вай.?фай|интернет|сети|сеть'),('cleaning',r'гряз|мусор|убор|загряз'),('property',r'стул|стол|мебел|ручк|окн|двер'),('equipment',r'проектор|компьютер|ноутбук|принтер|монитор|клавиатур|мыш')]:
  if re.search(pattern,t): r['category']=cat; break
 if re.search(r'не работа|не включ|не печат|не горит|не откры|не закры|слома|повреж|завис|пропал|нет (?:свет|интернет|сигнал)|гряз|мусор|течет|протеч|перегрев|неисправ|не подключ|не показы|шум',t):
  r.update(kind='fault',confidence='high',message='Похоже, требуется помощь сотрудника. Я подготовил категорию и черновик. Проверьте место и описание, затем подтвердите отправку заявки.')
  if 'принтер' in t: r.update(knowledge_id='printer',message=r['message']+' Можно выполнить безопасную первичную проверку из инструкции.')
  if re.search(r'во всем|во всей|перегрев|протеч',t): r['priority']='high'
  return r
 article=None
 if re.search(r'статус|отслежи',t): article='tracking'
 elif 'категори' in t: article='category'
 elif re.search(r'сообщить|оформить|создать заявку',t): article='fault'
 elif 'проектор' in t and re.search(r'как|подключ|настро|дублир',t): article='projector'
 elif 'принтер' in t and re.search(r'как|провер',t): article='printer'
 elif re.search(r'компьютер|ноутбук',t) and re.search(r'правил|пользоваться|работать|можно ли',t): article='computer'
 if article:
  kb=next(x for x in KNOWLEDGE if x['id']==article)
  r.update(kind='question',confidence='high',should_create=False,knowledge_id=article,source=kb['source'],message='Нашёл проверенную инструкцию. Если она не помогла или оборудование неисправно, создайте заявку.')
 elif len(t.split())<5 and r['category']=='other': r.update(kind='clarify',message='Что именно случилось и в каком помещении? Укажите оборудование или предмет, симптомы и когда вы их заметили.')
 return r
